"""Actual paired HTTP + Chromium phone; physical Android/TV/desktop input not asserted."""
from test_operations_remote import OperationsRemote
class ExpeditionRemote(OperationsRemote):
 def test_field_paired_request_and_follow_use_one_authoritative_world(self):
  pc=self.page(pc=True);pc.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');phone=self.page(width=390,height=844);self.tab(phone,'icarus');phone.wait_for_selector('.expedition-ops');phone.locator('.field-request').click();pc.wait_for_function('!!__icarusSoak.snapshot().missions.asteroid?.ops44')
  for i in range(40):
   pc.evaluate('__icarusSoak.advance(10)');m=pc.evaluate('__icarusSoak.snapshot().missions.asteroid')
   if m and m['ops44']['stage']=='field':break
  self.assertEqual(m['ops44']['stage'],'field');phone.wait_for_function('document.querySelector(".field-status").textContent.includes("field")');phone.locator('.field-members button').first.click();phone.wait_for_function('document.querySelector(".obs-status").textContent.includes("FOLLOW")');self.assertTrue(phone.locator('.obs-select').input_value().startswith('BODY-'),str((phone.locator('.obs-select').input_value(),phone.locator('.obs-status').inner_text(),pc.evaluate('__icarusSoak.observation().rooms.filter(r=>r.kind==="field")'))));self.assertNotIn('COVERAGE UNAVAILABLE',phone.locator('.obs-status').inner_text());self.assertEqual(phone.evaluate('typeof ICARUSExpeditionOps'),'undefined');self.assertEqual(phone.evaluate('typeof ICARUSFieldEvidence'),'undefined');self.assertEqual(phone.evaluate('typeof __icarusSoak'),'undefined');self.assertLessEqual(phone.evaluate('document.documentElement.scrollWidth'),392);self.assertNotIn('expeditions',self.m.ICARUS_BRIDGE['telemetry'])
 def test_field_remote_recall_attempts_real_return_and_receives_evidence(self):
  pc=self.page(pc=True);pc.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');phone=self.page(width=768,height=1024);self.tab(phone,'icarus');phone.wait_for_selector('.expedition-ops');phone.locator('.field-request').click();pc.wait_for_function('!!__icarusSoak.snapshot().missions.asteroid?.ops44')
  for i in range(40):
   pc.evaluate('__icarusSoak.advance(10)');m=pc.evaluate('__icarusSoak.snapshot().missions.asteroid')
   if m and m['ops44']['stage']=='field' and m['ops44']['edge']:break
  self.assertEqual(m['ops44']['stage'],'field');phone.wait_for_function('!document.querySelector(".field-recall").disabled');phone.locator('.field-recall').click();pc.wait_for_function('!!__icarusSoak.snapshot().missions.asteroid?.ops44.pendingRecall');pc.evaluate('__icarusSoak.advance(2)');s=pc.evaluate('__icarusSoak.snapshot()');self.assertTrue(s['missions']['asteroid']);self.assertTrue(any(p.get('expeditionAway')=='asteroid' for p in s['crew']));pc.evaluate('__icarusSoak.advance(200)');s=pc.evaluate('__icarusSoak.snapshot()');self.assertIsNone(s['missions']['asteroid']);self.assertEqual(s['expeditionOperations']['history'][-1]['reason'],'authorized_recall');self.assertEqual(s['resourceAudit'],[]);phone.wait_for_function('document.querySelector(".field-history").textContent.includes("authorized_recall")');self.assertTrue(s['fieldEvidence']['archive']);phone.locator('.expedition-ops summary').filter(has_text='Significant field evidence').click();phone.locator('.field-view').click();self.assertIn('RECONSTRUCTION',phone.locator('.field-record-label').inner_text());self.assertTrue(all('no recorded video' in r['recordingAvailability'] for r in s['fieldEvidence']['archive']))
 def test_field_unpaired_and_invalid_requests_rejected_and_duplicate_request_runs_once(self):
  pc=self.page(pc=True);pc.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');auth={'Authorization':'Bearer test-client'}
  self.assertEqual(self.req('/api/icarus/dispatch',{'command':'expedition:request:survey:auto','requestId':'field-unpaired'})[0],401)
  for c in ['expedition:request:survey:99','expedition:request:secret:auto','expedition:sensitivity:0','expedition:recall:bad']:
   self.assertEqual(self.req('/api/icarus/dispatch',{'command':c,'requestId':'bad-'+c},auth)[0],400)
  payload={'command':'expedition:request:survey:auto','requestId':'field-once'};a=self.req('/api/icarus/dispatch',payload,auth);b=self.req('/api/icarus/dispatch',payload,auth);self.assertEqual(a[1]['queued'],b[1]['queued']);pc.wait_for_function('!!__icarusSoak.snapshot().missions.asteroid?.ops44');self.assertEqual(pc.evaluate('__icarusSoak.snapshot().director.registry.filter(j=>j.type==="field-survey").length'),1)
